 private void addCompactLiveQuote(){final TextView p=t("Veri yükleniyor…",27,Color.WHITE,true),ch=t("",14,MUTED,true);body.addView(p);body.addView(ch);final String symbol=selectedSymbol;uiIo.execute(()->{try{java.util.List<MarketDataService.Candle>d=MarketDataService.fetchSeries(symbol,"5d","5m",200);if(d==null||d.size()<2)return;double price=d.get(d.size()-1).close,prev=d.get(d.size()-2).close;MarketDataService.Spot sp=MarketDataService.latestSpot(symbol);if(sp!=null&&sp.price>0)price=sp.price;final double fp=price,fc=price-prev,pc=prev==0?0:(price-prev)/prev*100d;runOnUiThread(()->{if(!symbol.equals(selectedSymbol))return;p.setText(String.format(java.util.Locale.GERMANY,"%.2f%s",fp,currency(symbol)));ch.setText(String.format(java.util.Locale.GERMANY,"%+.2f (%+.2f%%)",fc,pc));ch.setTextColor(fc>=0?GREEN:RED);});}catch(Exception ignored){runOnUiThread(()->p.setText("Fiyat alınamadı"));}});}
