 private String[] singleSearchUniverse(String market){if("ABD".equals(market))return GlobalStockUniverse.USA;if("Almanya".equals(market))return GlobalStockUniverse.GERMANY;if("Tümü".equals(market)){String[] b=BistUniverse.ENTRIES,d=GlobalStockUniverse.GERMANY,u=GlobalStockUniverse.USA;String[] all=new String[b.length+d.length+u.length];System.arraycopy(b,0,all,0,b.length);System.arraycopy(d,0,all,b.length,d.length);System.arraycopy(u,0,all,b.length+d.length,u.length);return all;}return BistUniverse.ENTRIES;}
 private String singleSearchSymbol(String entry,String market){String code=GlobalStockUniverse.code(entry);if("Almanya".equals(market))return code+".DE";if("ABD".equals(market))return code;if("Tümü".equals(market)){for(String e:GlobalStockUniverse.GERMANY)if(e.equals(entry))return code+".DE";for(String e:GlobalStockUniverse.USA)if(e.equals(entry))return code;}return code+".IS";}
 private String searchMarketTag(String entry,String market){if(!"Tümü".equals(market))return market;if(java.util.Arrays.asList(GlobalStockUniverse.GERMANY).contains(entry))return "Almanya";if(java.util.Arrays.asList(GlobalStockUniverse.USA).contains(entry))return "ABD";return "BIST";}
 private void showSymbolSearchDialog(){final LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(12),dp(4),dp(12),0);final TextView market=pill("Borsa: "+selectedMarket+" ▾",PANEL);box.addView(market,new LinearLayout.LayoutParams(-1,dp(42)));final android.widget.AutoCompleteTextView input=new android.widget.AutoCompleteTextView(this);input.setHint("Kod veya şirket adı yazın…");input.setSingleLine(true);input.setThreshold(1);input.setTextColor(Color.WHITE);input.setHintTextColor(MUTED);input.setBackgroundColor(PANEL);box.addView(input,new LinearLayout.LayoutParams(-1,dp(48)));final String[] searchMarket={selectedMarket};final java.util.ArrayList<String> labels=new java.util.ArrayList<>(),entries=new java.util.ArrayList<>();final android.widget.ArrayAdapter<String> adapter=new android.widget.ArrayAdapter<String>(this,android.R.layout.simple_dropdown_item_1line,labels);input.setAdapter(adapter);final java.util.function.Consumer<String> filter=(query)->{labels.clear();entries.clear();String needle=query==null?"":query.trim().toUpperCase(java.util.Locale.ROOT);if(!needle.isEmpty())for(String e:singleSearchUniverse(searchMarket[0])){if(e.toUpperCase(java.util.Locale.ROOT).contains(needle)){entries.add(e);labels.add("["+searchMarketTag(e,searchMarket[0])+"] "+e);if(labels.size()>=40)break;}}adapter.notifyDataSetChanged();if(!labels.isEmpty())input.showDropDown();};input.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence x,int a,int b,int c){}public void onTextChanged(CharSequence x,int a,int b,int c){filter.accept(x.toString());}public void afterTextChanged(android.text.Editable e){}});market.setOnClickListener(v->{final String[] ms={"BIST","ABD","Almanya","Tümü"};new android.app.AlertDialog.Builder(this).setTitle("Analiz borsası").setItems(ms,(d,which)->{searchMarket[0]=ms[which];market.setText("Borsa: "+searchMarket[0]+" ▾");input.setText("");input.requestFocus();}).show();});final android.app.AlertDialog dialog=new android.app.AlertDialog.Builder(this).setTitle("Tek Hisse Analizi").setView(box).setPositiveButton("Analiz Et",null).setNegativeButton("İptal",null).create();final String[] picked={null};input.setOnItemClickListener((p,v,pos,id)->{if(pos>=0&&pos<entries.size()){picked[0]=entries.get(pos);input.setText(labels.get(pos));input.setSelection(input.length());}});dialog.setOnShowListener(x->dialog.getButton(android.app.AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String raw=input.getText().toString().trim();if(raw.isEmpty())return;String entry=picked[0];String q;if(entry!=null)q=singleSearchSymbol(entry,searchMarket[0]);else{q=raw.toUpperCase(java.util.Locale.ROOT);if("BIST".equals(searchMarket[0])&&!q.endsWith(".IS")&&!q.startsWith("^"))q+=".IS";if("Almanya".equals(searchMarket[0])&&!q.endsWith(".DE"))q+=".DE";}selectedMarket="Tümü".equals(searchMarket[0])&&entry!=null?searchMarketTag(entry,searchMarket[0]):searchMarket[0];selectedSymbol=q;lastRadarSymbol=q;getSharedPreferences("borsaradar",MODE_PRIVATE).edit().putString("selectedMarket",selectedMarket).putString("lastRadarSymbol",q).apply();dialog.dismiss();showDetail();}));dialog.show();}

