 private void loadDetailMarketMetrics(){final String symbol=selectedSymbol;uiIo.execute(()->{try{java.util.List<MarketDataService.Candle>d=MarketDataService.fetchSeries(symbol,"1y","1d",280);if(d==null||d.size()<20)return;int n=d.size();MarketDataService.Candle last=d.get(n-1);double price=last.close,lo52=Double.MAX_VALUE,hi52=-Double.MAX_VALUE,avgVol=0;int st=Math.max(0,n-252);for(int i=st;i<n;i++){lo52=Math.min(lo52,d.get(i).low);hi52=Math.max(hi52,d.get(i).high);avgVol+=d.get(i).volume;}avgVol/=Math.max(1,n-st);MarketDataService.Spot sp=MarketDataService.latestSpot(symbol);if(sp!=null&&sp.price>0)price=sp.price;ShortPulseEngine.Result p=ShortPulseEngine.analyze(d,symbol,selectedProfile);int dayPos=last.high<=last.low?50:(int)Math.round((price-last.low)/(last.high-last.low)*100);int yearPos=hi52<=lo52?50:(int)Math.round((price-lo52)/(hi52-lo52)*100);dayPos=Math.max(0,Math.min(100,dayPos));yearPos=Math.max(0,Math.min(100,yearPos));final int fdp=dayPos,fyp=yearPos;final String qm=String.format(java.util.Locale.GERMANY,"Rel. Hacim x%.2f   ATR %.2f%%   RSI7 %.1f\nKalite %.0f/100   Risk %.0f/100   Rejim %.0f\nBRX %.0f   BRQ %.0f   BRF %.0f",p.relativeVolume,p.atrPct,p.rsi7,p.qualityScore,p.riskScore,p.regimeScore,p.brx,p.brq,p.brf);final String dr=String.format(java.util.Locale.GERMANY,"%.2f%s   ← gün →   %.2f%s",last.low,currency(symbol),last.high,currency(symbol));final String yr=String.format(java.util.Locale.GERMANY,"%.2f%s   ← 52 hafta →   %.2f%s",lo52,currency(symbol),hi52,currency(symbol));runOnUiThread(()->{if(!symbol.equals(selectedSymbol))return;if(quickMetrics!=null)quickMetrics.setText(qm);if(dailyRangeBar!=null)dailyRangeBar.setProgress(fdp);if(yearRangeBar!=null)yearRangeBar.setProgress(fyp);if(dailyRangeText!=null)dailyRangeText.setText(dr);if(yearRangeText!=null)yearRangeText.setText(yr);});}catch(Exception ignored){}});}

