 private void loadChartAnalytics(String period){final String symbol=selectedSymbol;final String p=period;uiIo.execute(()->{try{String range="1mo",interval="1d";if("1G".equals(p)){range="1d";interval="5m";}else if("1H".equals(p)){range="5d";interval="5m";}else if("3A".equals(p))range="3mo";else if("6A".equals(p))range="6mo";else if("1Y".equals(p))range="1y";else if("2Y".equals(p))range="2y";java.util.List<MarketDataService.Candle>d=MarketDataService.fetchSeries(symbol,range,interval,520);if(d==null||d.size()<10)return;int n=d.size(),e=n-1;double price=d.get(e).close,ma20=ema(d,Math.min(20,n),e),ma50=ema(d,Math.min(50,n),e),ma200=ema(d,Math.min(200,n),e),g=0,l=0,hi=-1e99,lo=1e99,vol=0;int start=Math.max(1,n-14);for(int i=start;i<n;i++){double z=d.get(i).close-d.get(i-1).close;if(z>=0)g+=z;else l-=z;hi=Math.max(hi,d.get(i).high);lo=Math.min(lo,d.get(i).low);vol+=d.get(i).volume;}double rsi=100-(100/(1+(l==0?100:g/l))),macd=ema(d,Math.min(12,n),e)-ema(d,Math.min(26,n),e),stoch=hi==lo?50:100*(price-lo)/(hi-lo);String txt=String.format(java.util.Locale.GERMANY,"%s • %s\nSon %.2f%s\nEMA20 %.2f • EMA50 %.2f • EMA200 %.2f\nRSI %.1f • MACD %.2f • Stoch %.1f\nAralık %.2f – %.2f • Hacim %s",symbol,p,price,currency(symbol),ma20,ma50,ma200,rsi,macd,stoch,lo,hi,formatVolume(vol));runOnUiThread(()->{if(symbol.equals(selectedSymbol)&&chartInfo!=null)chartInfo.setText(txt);});}catch(Exception ex){runOnUiThread(()->{if(symbol.equals(selectedSymbol)&&chartInfo!=null)chartInfo.setText("Grafik analizi alınamadı");});}});}
