 private void loadFeaturedHome(){final String market=selectedMarket;final String[][] base=featuredForMarket();uiIo.execute(()->{final java.util.ArrayList<String[]> rows=new java.util.ArrayList<>();for(String[] q:base){String s=q[0];try{java.util.List<MarketDataService.Candle>d=MarketDataService.fetchSeries(s,"6mo","1d",180);if(d==null||d.size()<35){rows.add(new String[]{s,"—","—","VERİ YOK"});continue;}int n=d.size();double price=d.get(n-1).close,prev=d.get(n-2).close;MarketDataService.Spot sp=MarketDataService.latestSpot(s);if(sp!=null&&sp.price>0)price=sp.price;ShortPulseEngine.Result p=ShortPulseEngine.analyze(d,s,selectedProfile);double pct=prev==0?0:(price-prev)/prev*100;String sig=p.recommendation.contains("SAT")?"SAT":p.recommendation.contains("AL")?"AL":"İZLE";rows.add(new String[]{s,String.format(java.util.Locale.GERMANY,"%.2f%s",price,currency(s)),(Double.isNaN(pct)?"—":String.format(java.util.Locale.GERMANY,"%+.2f%%",pct)),sig});}catch(Exception ex){rows.add(new String[]{s,"—","—","VERİ YOK"});}}runOnUiThread(()->{if(!market.equals(selectedMarket)||featuredContainer==null)return;featuredContainer.removeAllViews();for(String[] s:rows){LinearLayout card=card();card.setOrientation(LinearLayout.HORIZONTAL);TextView code=t(s[0],13,Color.WHITE,true);TextView pr=t(s[1]+"  "+s[2],10,s[2].startsWith("-")?RED:GREEN,true);pr.setGravity(Gravity.CENTER);TextView sig=t(s[3],9,"AL".equals(s[3])?GREEN:"SAT".equals(s[3])?RED:AMBER,true);sig.setGravity(Gravity.CENTER);final String sym=s[0];card.setOnClickListener(v->{selectedSymbol=sym;lastRadarSymbol=sym;getSharedPreferences("borsaradar",MODE_PRIVATE).edit().putString("lastRadarSymbol",sym).apply();showDetail();});card.addView(code,new LinearLayout.LayoutParams(0,dp(38),1));card.addView(pr,new LinearLayout.LayoutParams(dp(150),dp(38)));card.addView(sig,new LinearLayout.LayoutParams(dp(58),dp(38)));featuredContainer.addView(card);Space spc=new Space(this);featuredContainer.addView(spc,new LinearLayout.LayoutParams(1,dp(5)));}});});}
 private void loadHomeMarketSummary(){final String market=selectedMarket;final String[][] idx={{"BIST 100","^XU100"},{"DAX","^GDAXI"},{"S&P 500","^GSPC"},{"NASDAQ","^IXIC"}};uiIo.execute(()->{StringBuilder sb=new StringBuilder();for(String[] q:idx){try{java.util.List<MarketDataService.Candle>d=MarketDataService.fetchSeries(q[1],"5d","1d",10);if(d==null||d.size()<2){sb.append(q[0]).append("  —\n");continue;}double p=d.get(d.size()-1).close,prev=d.get(d.size()-2).close;MarketDataService.Spot spot=MarketDataService.latestSpot(q[1]);if(spot!=null&&spot.price>0)p=spot.price;double pct=prev==0?0:(p-prev)/prev*100;sb.append(String.format(java.util.Locale.GERMANY,"%s  %.2f  %+.2f%%\n",q[0],p,pct));}catch(Exception ex){sb.append(q[0]).append("  —\n");}}final String txt=sb.toString().trim();runOnUiThread(()->{if(market.equals(selectedMarket)&&homeMarketSummary!=null)homeMarketSummary.setText(txt);});});}
