 private void loadFundamentalValuation(final LinearLayout card){final String symbol=selectedSymbol;uiIo.execute(()->{try{MarketDataService.Fundamentals f=MarketDataService.fetchFundamentals(symbol);MarketDataService.Spot sp=MarketDataService.latestSpot(symbol);double price=sp==null?Double.NaN:sp.price;String state="NORMAL";int col=MUTED;if(!Double.isNaN(f.priceToBook)){if(f.priceToBook>=4){state="UYARI • DEFTER DEĞERİNİN ÇOK ÜZERİNDE";col=RED;}else if(f.priceToBook>=2){state="PAHALI • DEFTER DEĞERİNİN ÜZERİNDE";col=AMBER;}else if(f.priceToBook>0&&f.priceToBook<=0.75){state="İSKONTOLU • DEFTER DEĞERİNİN ALTINDA";col=GREEN;}}final int color=col;final String txt=String.format(java.util.Locale.GERMANY,"Defter Değeri   %s\nPD/DD            %s\nF/K              %s\n\n%s\nKaynak: %s",Double.isNaN(f.bookValuePerShare)?"—":String.format(java.util.Locale.GERMANY,"%.2f%s",f.bookValuePerShare,currency(symbol)),Double.isNaN(f.priceToBook)?"—":String.format(java.util.Locale.GERMANY,"%.2f",f.priceToBook),Double.isNaN(f.trailingPE)?"—":String.format(java.util.Locale.GERMANY,"%.2f",f.trailingPE),state,f.source);runOnUiThread(()->{if(symbol.equals(selectedSymbol)&&card!=null){if(card.getChildCount()>1)card.removeViews(1,card.getChildCount()-1);card.addView(t(txt,11,color,true));}});}catch(Exception ex){}});}

 private void loadFinancialSnapshot(){final String symbol=selectedSymbol;uiIo.execute(()->{try{java.util.List<MarketDataService.Candle>d=MarketDataService.fetchSeries(symbol,"2y","1d",520);if(d==null||d.size()<60)return;int n=d.size(),y=Math.max(0,n-252);double price=d.get(n-1).close,hi=-1e99,lo=1e99,sum=0,sum2=0,vol=0;for(int i=y;i<n;i++){MarketDataService.Candle x=d.get(i);hi=Math.max(hi,x.high);lo=Math.min(lo,x.low);sum+=x.close;sum2+=x.close*x.close;vol+=x.volume;}MarketDataService.Spot sp=MarketDataService.latestSpot(symbol);if(sp!=null&&sp.price>0)price=sp.price;int count=n-y;double avg=sum/count,var=Math.max(0,sum2/count-avg*avg),sd=Math.sqrt(var),fromLow=lo==0?0:(price/lo-1)*100,toHigh=price==0?0:(hi/price-1)*100,pos=hi==lo?50:(price-lo)/(hi-lo)*100;String txt=String.format(java.util.Locale.GERMANY,"Güncel fiyat       %.2f%s\n1Y ortalama        %.2f%s\n52H düşük          %.2f%s\n52H yüksek         %.2f%s\n52H konumu         %.0f%%\nDüşükten fark      %+.1f%%\nYükseğe mesafe    %+.1f%%\n1Y oynaklık (σ)   %.2f\nOrt. günlük hacim  %s\n\nTemel oranlar: veri kaynağı bekleniyor",price,currency(symbol),avg,currency(symbol),lo,currency(symbol),hi,currency(symbol),pos,fromLow,toHigh,sd,formatVolume(vol/count));runOnUiThread(()->{if(symbol.equals(selectedSymbol)&&financialData!=null)financialData.setText(txt);});}catch(Exception ex){runOnUiThread(()->{if(symbol.equals(selectedSymbol)&&financialData!=null)financialData.setText("Finansal/değerleme verisi alınamadı");});}});}
 private String sectorFor(String s){
  String z=MarketDataService.normalizeSymbol(s).replace(".IS","");
  if(java.util.Arrays.asList("AKBNK","ALBRK","GARAN","HALKB","ICBCT","ISCTR","KLNMA","SKBNK","TSKB","VAKBN","YKBNK").contains(z))return "Bankacılık";
  if(java.util.Arrays.asList("AKSEN","AKSUE","AYDEM","AYEN","BIOEN","CANTE","CONSE","CWENE","ENERY","ENJSA","ESEN","GWIND","HUNER","IZENR","KARYE","MAGEN","NATEN","ODAS","SMRTG","ZOREN").contains(z))return "Enerji";
  if(java.util.Arrays.asList("THYAO","TAVHL","PGSUS","CLEBI","GRSEL").contains(z))return "Ulaştırma";
  if(java.util.Arrays.asList("FROTO","TOASO","DOAS","KARSN","OTKAR","TTRAK","TMSN","ASUZU").contains(z))return "Otomotiv";
  if(java.util.Arrays.asList("BIMAS","MGROS","SOKM","BIZIM","CRFSA").contains(z))return "Perakende";
  if(java.util.Arrays.asList("TCELL","TTKOM","ALCTL").contains(z))return "Telekom";
  if(java.util.Arrays.asList("EREGL","ISDMR","KRDMA","KRDMB","KRDMD","IZMDC","KCAER","BRSAN").contains(z))return "Demir-Çelik";
  if(java.util.Arrays.asList("PETKM","AKSA","ALKIM","GUBRF","HEKTS","KMPUR").contains(z))return "Kimya/Petrokimya";
  if(z.endsWith("GYO")||z.endsWith("GY"))return "GYO";
  if(java.util.Arrays.asList("ARDYZ","ATATP","DESPC","DGATE","EDATA","ESCOM","FONET","HTTBT","INDES","KFEIN","LOGO","MIATK","NETAS","PENTA","REEDR").contains(z))return "Teknoloji";
  if(java.util.Arrays.asList("AEFES","BANVT","CCOLA","DARDL","EKSUN","FADE","FRIGO","KERVT","PENGD","TATGD","ULKER","YYLGD").contains(z))return "Gıda/İçecek";
  if(java.util.Arrays.asList("DEVA","ECILC","EGEPO","GENIL","MPARK","SELEC","TRILC").contains(z))return "Sağlık/İlaç";
  if(java.util.Arrays.asList("AGHOL","ALARK","BERA","DOHOL","ECZYT","GLYHO","GSDHO","KCHOL","SAHOL").contains(z))return "Holding";
  return "Diğer";
 }
 private boolean sectorMatches(String s){return "Tüm Sektörler".equals(selectedSector)||selectedSector.equals(sectorFor(s));}
 private void chooseSector(){
  final String[] sectors={"Tüm Sektörler","Bankacılık","Enerji","Ulaştırma","Otomotiv","Perakende","Telekom","Demir-Çelik","Kimya/Petrokimya","GYO","Teknoloji","Gıda/İçecek","Sağlık/İlaç","Holding","Diğer"};
  new android.app.AlertDialog.Builder(this).setTitle("Sektör seç").setItems(sectors,(d,w)->{selectedSector=sectors[w];renderRadarRows(cachedRadarRows);showRadar();}).show();
 }
 private int sectorUniverseCount(){int n=0;for(String s:radarUniverse())if(sectorMatches(s))n++;return n;}
