 private void loadPaperValue(){final String symbol=selectedSymbol;uiIo.execute(()->{try{java.util.List<MarketDataService.Candle>d=MarketDataService.fetchSeries(symbol,"2y","1d",520);if(d==null||d.size()<120)return;int n=d.size();double now=d.get(n-1).close,sum=0,w=0;int start=Math.max(0,n-252);for(int i=start;i<n;i++){double weight=1d+(i-start)/(double)Math.max(1,n-start);sum+=d.get(i).close*weight;w+=weight;}double weightedAvg=sum/w;double hi=d.get(start).high,lo=d.get(start).low;for(int i=start;i<n;i++){hi=Math.max(hi,d.get(i).high);lo=Math.min(lo,d.get(i).low);}ShortPulseEngine.Result r=ShortPulseEngine.analyze(d,symbol,selectedProfile);double technicalAdj=Math.max(-0.12,Math.min(0.12,r.score/40d));double paper=weightedAvg*(1d+technicalAdj);paper=Math.max(lo,Math.min(hi,paper));double upside=now==0?0:(paper/now-1d)*100d;String state=upside>=25?"ÇOK UCUZ":upside>=12?"UCUZ":upside<=-20?"PAHALI":upside<=-10?"YÜKSEK":"DENGE";final String txt=String.format(java.util.Locale.GERMANY,"Model değer* %.2f%s • Fark %+.1f%% • %s",paper,currency(symbol),upside,state);runOnUiThread(()->{if(symbol.equals(selectedSymbol)&&paperValue!=null){paperValue.setText(txt);paperValue.setTextColor(upside>=12?GREEN:upside<=-10?RED:AMBER);}});}catch(Exception e){runOnUiThread(()->{if(symbol.equals(selectedSymbol)&&paperValue!=null)paperValue.setText("Model değer hesaplanamadı");});}});}
 private void loadValueHistory(){final String symbol=selectedSymbol;uiIo.execute(()->{try{java.util.List<MarketDataService.Candle>d=MarketDataService.fetchSeries(symbol,"2y","1d",520);if(d==null||d.size()<40)return;int n=d.size();double now=d.get(n-1).close;int y1=Math.max(0,n-252),y2=0;double p1=d.get(y1).close,p2=d.get(y2).close,sum1=0,sum2=0;for(int i=y1;i<n;i++)sum1+=d.get(i).close;for(int i=0;i<n;i++)sum2+=d.get(i).close;double a1=sum1/(n-y1),a2=sum2/n;double discount1=a1==0?0:(now/a1-1)*100,discount2=a2==0?0:(now/a2-1)*100;String valueSignal=(discount1<=-20&&discount2<=-20)?"DEĞERSEL AL":(discount1<=-10||discount2<=-15)?"UCUZ / İZLE":(discount1>=20&&discount2>=20)?"PAHALI":"NORMAL";final String txt=String.format(java.util.Locale.GERMANY,"1Y önce %.2f%s • 1Y ort. %.2f%s (%+.1f%%)\n2Y önce %.2f%s • 2Y ort. %.2f%s (%+.1f%%) • %s",p1,currency(symbol),a1,currency(symbol),discount1,p2,currency(symbol),a2,currency(symbol),discount2,valueSignal);runOnUiThread(()->{if(symbol.equals(selectedSymbol)&&valueHistory!=null){valueHistory.setText(txt);valueHistory.setTextColor(valueSignal.contains("AL")?GREEN:valueSignal.equals("PAHALI")?RED:AMBER);}});}catch(Exception e){runOnUiThread(()->{if(symbol.equals(selectedSymbol)&&valueHistory!=null)valueHistory.setText("Değer geçmişi alınamadı");});}});}
